    return RawValuesInsertable({
      if (assetKey != null) 'asset_key': assetKey,
      if (dimension != null) 'dimension': dimension,
      if (baseVersion != null) 'base_version': baseVersion,
      if (rowid != null) 'rowid': rowid,
    });
