          : Value(documentTitle),
      chapterLabel: chapterLabel == null && nullToAbsent
          ? const Value.absent()
          : Value(chapterLabel),
      bookKey: bookKey == null && nullToAbsent
          ? const Value.absent()
          : Value(bookKey),
      sectionIndex: sectionIndex == null && nullToAbsent
