    return (StringBuffer('SeriesRow(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('coverSource: $coverSource, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
