      {required this.id,
      required this.name,
      required this.collectionType,
      this.coverSource,
      this.coverPath,
      required this.sortOrder,
      required this.createdAt,
      required this.orderUpdatedAt,
      this.anilistId,
      this.audioTrackId,
      this.subtitleDelayMs});
