      {required this.collectionId,
      required this.source,
      required this.subjectId,
      required this.title,
      this.originalTitle,
      this.summary,
      this.airDate,
      this.rating,
      this.ratingCount,
      this.episodeCount,
      this.tagsJson,
      this.infoboxJson,
      this.backdropPath,
      this.detailUrl,
      required this.scrapedAt});
